// Turns the form's product URLs into the payload Bright Data expects.
// The reviews dataset accepts `url` and nothing else - days_range, sort_by and
// filter_by_star are each rejected with a validation_error - so recency and
// star filtering happen later, in Rank Themes And Gaps.
const cfg = $('Set Analysis Config').first().json;

const parse = (raw, role) =>
  String(raw || '')
    .split(/[\n,]/)
    .map((s) => s.trim())
    .filter(Boolean)
    .map((line) => {
      // No URL constructor in the Code node sandbox, so the ASIN comes out
      // with a regex.
      const m = line.match(/\/(?:dp|gp\/product)\/([A-Z0-9]{10})/i);
      if (!m) {
        throw new Error(
          `"${line}" is not an Amazon product URL. Expected something like https://www.amazon.com/dp/B0CHWRXH8B`
        );
      }
      return { asin: m[1].toUpperCase(), url: line.split('?')[0], role };
    });

const mine = parse(cfg.my_product_url, 'mine');
const rivals = parse(cfg.competitor_urls, 'competitor');

if (mine.length !== 1) {
  throw new Error('Give exactly one product of your own in my_product_url.');
}
if (!rivals.length) {
  throw new Error('Add at least one competitor product URL.');
}

// De-duplicate, and keep the run small enough to stay cheap.
const seen = new Set();
const products = [...mine, ...rivals].filter((p) => {
  if (seen.has(p.asin)) return false;
  seen.add(p.asin);
  return true;
}).slice(0, 4);

return [{ json: { products, payload: products.map((p) => ({ url: p.url })) } }];

// Bright Data answers validation errors with a body, not always a status code,
// and neverError hides the status anyway. Read the body.
// single-item input: the trigger endpoint returns one JSON object per call.
const res = $input.first().json;

if (res.error || res.errors) {
  const detail = JSON.stringify(res.errors || res.error).slice(0, 400);
  throw new Error(`Bright Data rejected the scrape request: ${detail}`);
}
if (!res.snapshot_id) {
  throw new Error(
    `No snapshot_id came back from Bright Data. Check that your API key is valid and the response was: ${JSON.stringify(res).slice(0, 300)}`
  );
}

return [{ json: { snapshot_id: res.snapshot_id } }];

// The poll loop's guard rail. Without a cap this Wait -> Progress -> IF cycle
// spins forever on a stuck snapshot and burns executions all night.
const MAX_POLLS = 20; // 20 x 30s = 10 minutes
// single-item input: the progress endpoint returns one status object.
const res = $input.first().json;
const snapshotId = $('Check Scrape Accepted').first().json.snapshot_id;
const attempt = $runIndex + 1;

if (res.status === 'failed') {
  throw new Error(
    `Bright Data reported the snapshot failed: ${JSON.stringify(res).slice(0, 300)}`
  );
}
if (res.status !== 'ready' && attempt >= MAX_POLLS) {
  throw new Error(
    `Snapshot ${snapshotId} was still "${res.status}" after ${attempt} checks. Large review pulls can take longer - raise MAX_POLLS in Evaluate Scrape Progress, or lower reviews_per_product.`
  );
}

return [
  {
    json: {
      snapshot_id: snapshotId,
      status: res.status,
      attempt,
      records: res.records || 0,
    },
  },
];

// One n8n item per review, so $input.all() - $input.first() would silently
// keep a single review and every downstream count would be wrong.
const rows = $input.all().map((i) => i.json);
// single-item input: Build Scrape Input deliberately emits one item holding the
// whole product list, so .first() is the only item there is.
const products = $('Build Scrape Input').first().json.products;
const roleByAsin = Object.fromEntries(products.map((p) => [p.asin, p.role]));

// Bright Data returns several fields concatenated with themselves, e.g.
// "Verified Purchase, Verified Purchase" and
// "October 25, 2023Reviewed in the United States on October 25, 2023".
// Halve any string that is exactly its own first half repeated.
const undouble = (s) => {
  const t = String(s || '').trim();
  if (!t) return '';
  const half = t.length / 2;
  if (t.length % 2 === 0 && t.slice(0, half) === t.slice(half)) return t.slice(0, half);
  return t;
};

// The date field also glues the country sentence onto the end of the date.
const cleanDate = (s) => {
  const t = undouble(s);
  const m = t.match(/^([A-Za-z]+ \d{1,2}, \d{4})/);
  return m ? m[1] : t.split('Reviewed in')[0].trim();
};

const out = [];
for (const r of rows) {
  if (r.error || r.warning) continue; // include_errors=true puts failures in the rows
  const asin = r.asin || r.variant_asin;
  if (!asin || !r.review_text) continue;
  out.push({
    json: {
      asin,
      role: roleByAsin[asin] || 'competitor',
      product_name: String(r.product_name || '').slice(0, 120),
      product_rating: r.product_rating,
      product_rating_count: r.product_rating_count,
      rating: Number(r.rating) || 0,
      title: undouble(r.review_header).slice(0, 200),
      text: String(r.review_text).replace(/\s+/g, ' ').trim().slice(0, 1200),
      posted: cleanDate(r.review_posted_date),
      verified: r.is_verified === true,
      helpful: Number(r.helpful_count) || 0,
    },
  });
}

if (!out.length) {
  throw new Error(
    'Bright Data returned no usable reviews. Check the product URLs are live Amazon listings with reviews.'
  );
}

return out;

// One item per product, because the Information Extractor downstream runs once
// per item - that is the whole loop, no Split In Batches needed.
const cfg = $('Set Analysis Config').first().json;
const minStars = Number(cfg.max_star_to_analyse) || 3;
const rows = $input.all().map((i) => i.json);

const byAsin = {};
for (const r of rows) {
  (byAsin[r.asin] = byAsin[r.asin] || []).push(r);
}

const out = [];
for (const [asin, all] of Object.entries(byAsin)) {
  // Critical reviews carry the signal. Five-star text is mostly "love it".
  const critical = all.filter((r) => r.rating && r.rating <= minStars);
  const praise = all.filter((r) => r.rating >= 4);
  const pick = [...critical, ...praise.slice(0, Math.ceil(critical.length / 2) || 5)];

  // Most-helpful first, so the character cap keeps the reviews other buyers
  // actually voted for rather than whatever came back first.
  pick.sort((a, b) => b.helpful - a.helpful);

  let budget = 14000;
  const lines = [];
  for (const r of pick) {
    const line = `[${r.rating}/5] ${r.title} :: ${r.text}`;
    if (budget - line.length < 0) break;
    budget -= line.length;
    lines.push(line);
  }

  const first = all[0];
  out.push({
    json: {
      asin,
      role: first.role,
      product_name: first.product_name,
      product_rating: first.product_rating,
      product_rating_count: first.product_rating_count,
      reviews_analysed: lines.length,
      reviews_total: all.length,
      critical_count: critical.length,
      review_blob: lines.join('\n'),
    },
  });
}

return out;

