// The Information Extractor ran once per product, so collect all of its output
// and re-attach the product metadata it does not carry.
const extracted = $input.all().map((i) => i.json);
const meta = $('Group Reviews By Product').all().map((i) => i.json);

const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').trim();

const products = extracted.map((e, idx) => {
  const m = meta[idx] || {};
  const out = e.output || e; // extractor nests under `output` on some versions
  return {
    asin: m.asin,
    role: m.role,
    product_name: m.product_name,
    product_rating: m.product_rating,
    reviews_analysed: m.reviews_analysed,
    critical_count: m.critical_count,
    complaints: Array.isArray(out.complaints) ? out.complaints : [],
    praise: Array.isArray(out.praise) ? out.praise : [],
    feature_requests: Array.isArray(out.feature_requests) ? out.feature_requests : [],
  };
});

const mine = products.find((p) => p.role === 'mine');
const rivals = products.filter((p) => p.role !== 'mine');

if (!mine) {
  throw new Error('Lost track of which product is yours between scraping and analysis.');
}

// The actual point of the workflow: a theme buyers complain about on your
// product and praise on a rival's is a competitive gap, not just a bug.
const rivalPraise = rivals.flatMap((r) =>
  r.praise.map((p) => ({ ...p, product_name: r.product_name, asin: r.asin }))
);

const gaps = [];
for (const c of mine.complaints) {
  const cWords = new Set(norm(c.theme).split(' ').filter((w) => w.length > 3));
  for (const p of rivalPraise) {
    const pWords = norm(p.theme).split(' ').filter((w) => w.length > 3);
    const shared = pWords.filter((w) => cWords.has(w));
    if (shared.length >= 1) {
      gaps.push({
        your_complaint: c.theme,
        their_strength: p.theme,
        competitor: p.product_name,
        severity: c.severity || 'medium',
        overlap: shared.join(', '),
      });
      break;
    }
  }
}

return [
  {
    json: {
      mine,
      rivals,
      gaps,
      gap_count: gaps.length,
      analysed_at: new Date().toISOString().slice(0, 10),
    },
  },
];

