// Splits into one row per finding for the sheet, and one Slack message.
// single-item input: the brief chain and Rank Themes And Gaps each emit exactly
// one item - the whole comparison, not one item per product.
const brief = $input.first().json.text || $input.first().json.output || '';
const data = $('Rank Themes And Gaps').first().json;
const mine = data.mine;

const rows = [];
for (const c of mine.complaints.slice(0, 10)) {
  rows.push({
    date: data.analysed_at,
    asin: mine.asin,
    product: mine.product_name,
    type: 'complaint',
    theme: c.theme,
    mentions: c.mentions || '',
    severity: c.severity || '',
    detail: c.quote || '',
  });
}
for (const g of data.gaps.slice(0, 10)) {
  rows.push({
    date: data.analysed_at,
    asin: mine.asin,
    product: mine.product_name,
    type: 'gap',
    theme: g.your_complaint,
    mentions: '',
    severity: g.severity,
    detail: `${g.competitor} is praised for: ${g.their_strength}`,
  });
}

// Amazon titles run past 100 characters, so cut them on a word boundary for
// display. Slicing blind leaves the reader with "...Carryi".
const short = (s, max = 55) => {
  const t = String(s || '');
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  return cut.slice(0, cut.lastIndexOf(' ') > 20 ? cut.lastIndexOf(' ') : max) + '...';
};

const top = mine.complaints
  .slice(0, 3)
  .map((c, i) => {
    const n = Number(c.mentions) || 0;
    return `${i + 1}. ${c.theme}${n ? ` (${n} mention${n === 1 ? '' : 's'})` : ''}`;
  })
  .join('\n');
const gapLines = data.gaps
  .slice(0, 3)
  .map(
    (g) => `- ${g.your_complaint} -> ${short(g.competitor)} wins on "${g.their_strength}"`
  )
  .join('\n');

const message = [
  `*Review gap analysis - ${short(mine.product_name, 70)}*`,
  `${mine.reviews_analysed} reviews read, ${mine.critical_count} critical. Rating ${mine.product_rating}.`,
  '',
  '*Top complaints*',
  top || '_none extracted_',
  '',
  `*Competitive gaps (${data.gap_count})*`,
  gapLines || '_no overlapping themes found_',
  '',
  brief,
].join('\n');

// One item carrying both payloads. Split Out turns `rows` into one item per
// theme for the sheet; the Slack node runs once and reads `message` from here.
// Appending this item directly would put a single row of message/rows/row_count
// in the sheet instead of one row per theme.
return [{ json: { message, rows, row_count: rows.length } }];
